def sum_of_divisors(x):
    sum_divisors = 0
    for i in range(1, int(x**0.5) + 1):
        if x % i == 0:
            sum_divisors += i
            if i != x // i:
                sum_divisors += x // i
    return sum_divisors

def count_solutions(A):
    count = 0
    for x in range(1, A + 1):
        if sum_of_divisors(x) == A:
            count += 1
    return count

# Read input
A = int(input())

# Output the result
print(count_solutions(A))
